import{_ as r,o as t,c as e,a2 as s}from"./chunks/framework.BXA5Pi9t.js";const p=JSON.parse('{"title":"Async I/O with Libcephfs - Dhairya Parmar, IBM","description":"","frontmatter":{"title":"Async I/O with Libcephfs - Dhairya Parmar, IBM","date":"2025-01-23T00:00:00.000Z","updated":"2025-01-24T00:00:00.000Z","tags":["CephFS","Asynchronous IO","Performance Optimization","Storage Networking","Ceph Storage"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Async_I_O_with_Libcephfs_-_Dhairya_Parmar_IBM.md","filePath":"posts/2025/Async_I_O_with_Libcephfs_-_Dhairya_Parmar_IBM.md","lastUpdated":1780459816000}'),o={name:"posts/2025/Async_I_O_with_Libcephfs_-_Dhairya_Parmar_IBM.md"};function i(n,a,l,h,g,_){return t(),e("div",null,[...a[0]||(a[0]=[s('<h3 id="会议纪要-cephfs异步io接口的开发与优化" tabindex="-1">会议纪要：CephFS异步IO接口的开发与优化 <a class="header-anchor" href="#会议纪要-cephfs异步io接口的开发与优化" aria-label="Permalink to &quot;会议纪要：CephFS异步IO接口的开发与优化&quot;">​</a></h3><p><strong>会议时间</strong>：未知<br><strong>主持人</strong>：Daria，IBM软件工程师，Ceph团队成员，主要负责MDS客户端和NFS模块。</p><h4 id="会议主题" tabindex="-1"><strong>会议主题</strong>： <a class="header-anchor" href="#会议主题" aria-label="Permalink to &quot;**会议主题**：&quot;">​</a></h4><ul><li><strong>CephFS（libcephfs）异步IO接口的开发与优化</strong></li></ul><h4 id="背景与问题" tabindex="-1"><strong>背景与问题</strong>： <a class="header-anchor" href="#背景与问题" aria-label="Permalink to &quot;**背景与问题**：&quot;">​</a></h4><ul><li><strong>默认接口的阻塞性问题</strong>：CephFS的默认接口是同步阻塞的，在高负载下，文件系统网关（如NFS Ganesha）的线程争用和等待时间过长，影响了系统的可扩展性和性能。</li><li><strong>NFS Ganesha的同步行为</strong>：NFS Ganesha客户端的同步行为导致在网络延迟或大IO操作时，线程长时间处于等待状态，从而降低了性能。</li></ul><h4 id="解决方案" tabindex="-1"><strong>解决方案</strong>： <a class="header-anchor" href="#解决方案" aria-label="Permalink to &quot;**解决方案**：&quot;">​</a></h4><ul><li><strong>异步IO接口的开发</strong>：为解决上述问题，开发了CephFS的异步IO接口，允许NFS Ganesha客户端在发起IO请求后立即释放线程，并在IO完成后通过回调机制通知客户端。</li><li><strong>异步IO的工作流程</strong>： <ol><li>NFS Ganesha客户端通过RPC调度器向CephFS发送异步IO请求。</li><li>CephFS注册回调函数，并在IO完成后通知NFS Ganesha客户端。</li><li>NFS Ganesha客户端的RPC调度器暂停任务并释放线程，直到IO完成后再恢复任务。</li></ol></li></ul><h4 id="优势" tabindex="-1"><strong>优势</strong>： <a class="header-anchor" href="#优势" aria-label="Permalink to &quot;**优势**：&quot;">​</a></h4><ul><li><strong>低延迟操作</strong>：异步IO接口减少了IO操作的等待时间，提高了系统的响应速度。</li><li><strong>低线程争用</strong>：通过减少线程等待时间，降低了线程争用，增强了系统的并发处理能力。</li><li><strong>高吞吐量和可扩展性</strong>：异步IO接口显著提高了系统的吞吐量和可扩展性。</li></ul><h4 id="当前进展" tabindex="-1"><strong>当前进展</strong>： <a class="header-anchor" href="#当前进展" aria-label="Permalink to &quot;**当前进展**：&quot;">​</a></h4><ul><li><strong>接口的测试与优化</strong>：已对异步IO接口进行了广泛的测试，修复了多个bug，并将相关补丁合并到主分支。</li><li><strong>零拷贝技术的实现</strong>：正在进行零拷贝技术的实现，以减少数据拷贝，进一步提升性能。</li><li><strong>NFS Ganesha的集成</strong>：异步IO接口已与NFS Ganesha集成，并进行了测试。</li></ul><h4 id="后续计划" tabindex="-1"><strong>后续计划</strong>： <a class="header-anchor" href="#后续计划" aria-label="Permalink to &quot;**后续计划**：&quot;">​</a></h4><ul><li><strong>Samba集成</strong>：未来计划将异步IO接口集成到Samba中，进一步提升Samba的性能。</li><li><strong>代码清理与模块化</strong>：将继续进行代码清理和模块化工作，以保持代码的可维护性和可扩展性。</li></ul><h4 id="总结" tabindex="-1"><strong>总结</strong>： <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;**总结**：&quot;">​</a></h4><ul><li>异步IO接口的开发解决了CephFS在高负载下的性能瓶颈问题，显著提升了系统的可扩展性和性能。</li><li>未来将继续优化接口，并计划将其集成到更多的文件系统网关中，以进一步提升CephFS的整体性能。</li></ul><p><strong>会议结束</strong>：感谢大家的参与。</p>',17)])])}const d=r(o,[["render",i]]);export{p as __pageData,d as default};
